'use strict';
const assert = require('node:assert/strict');
const { resolve } = require('./src');
const { satisfies } = require('./src/semver');

// caret zero rules
assert.equal(satisfies('0.3.9', '^0.2.0'), false);
assert.equal(satisfies('0.2.9', '^0.2.0'), true);
assert.equal(satisfies('0.0.4', '^0.0.3'), false);
assert.equal(satisfies('0.0.3', '^0.0.3'), true);

// backtracking must undo constraints of a rejected choice
const reg1 = {
  a: { '2.0.0': { b: '^2.0.0', c: '1.0.0' }, '1.0.0': { b: '^1.0.0' } },
  b: { '2.0.0': {}, '1.0.0': {} },
  c: { '2.0.0': {} },
};
assert.deepEqual(resolve(reg1, { a: '*' }), { a: '1.0.0', b: '1.0.0' });

// conflict with selected version: b selected 2.0.0, later c needs b 1 -> backtrack
const reg2 = {
  b: { '2.0.0': {}, '1.0.0': {} },
  c: { '1.0.0': { b: '1.0.0' } },
};
assert.deepEqual(resolve(reg2, { b: '*', c: '*' }), { b: '1.0.0', c: '1.0.0' });

// cycle
const reg3 = { x: { '1.0.0': { y: '*' } }, y: { '1.0.0': { x: '1.0.0' } } };
assert.deepEqual(resolve(reg3, { x: '*' }), { x: '1.0.0', y: '1.0.0' });

// missing package
assert.equal(resolve({}, { nope: '*' }), null);

// long chain
const reg4 = {};
const N = 100000;
for (let i = 0; i < N; i += 1) reg4['p' + i] = { '1.0.0': i + 1 < N ? { ['p' + (i + 1)]: '*' } : {} };
assert.equal(Object.keys(resolve(reg4, { p0: '*' })).length, N);

// long chain ending in conflict: must still terminate with null
reg4['p' + (N - 1)] = { '1.0.0': { p0: '2.0.0' } };
assert.equal(resolve(reg4, { p0: '*' }), null);

// eager validation of unreachable entries
assert.throws(() => resolve({ z: { 'bad': {} } }, {}), TypeError);
assert.deepEqual(resolve({}, {}), {});
console.log('smoke ok');
